// KMI MASTER 002.05/002.01 — Ana sayfa "Önceliklerim" kartı: gerçek görev kaynağından (task_floor MINE) sıralı ilk 5 iş.
// Kaynak yoksa/boşsa uydurma içerik göstermez. Yalnız okur; görev açma/kapama bu kartta yapılmaz.
import { h } from '../../../packages/ui/src/h.js';
import { rankHomeItems } from './homePriority.js';
import { buildAlerts, freshness } from './homeAlerts.js';
const pick = (o, a, b) => (o?.[a] !== undefined ? o[a] : o?.[b]);
export function normalizeTasks(tasks, reqs) {
    const rows = [];
    for (const t of tasks?.manual ?? []) {
        const rq = reqs?.get?.(t.id); rows.push({ id: t.id, title: t.title, status: t.status, autoGenerated: !!rq, requirementsDone: rq?.done ?? 0, requirementsTotal: rq?.total ?? 0, dueAt: pick(t, 'dueAt', 'due_at') ?? null, createdAt: pick(t, 'createdAt', 'created_at') ?? null,
            href: `#/gorevler?t=${encodeURIComponent(t.id)}` });
    }
    for (const d of tasks?.derived ?? []) {
        const route = d.route ?? null;
        rows.push({ id: `d-${pick(d, 'sourceId', 'source_id')}`, title: d.title, status: 'OPEN', dueAt: d.due ?? null, createdAt: null, href: route ? `#${route}` : '#/gorevler' });
    }
    return rows;
}
const TONE = { bad: '#f87171', warn: '#fbbf24', info: '#38bdf8' };
/** o: { reqs?: Map(taskId→{done,total}), approvalsPending?, loadedAt?, sources?, onRefresh? } */
export function renderPriorityCard(host, tasks, nowMs = Date.now(), o = {}) {
    if (!host) return;
    if (tasks === null || tasks === undefined) { host.replaceChildren(); return; } // henüz yüklenmedi / kaynak yok: hiçbir şey gösterme
    const rows = normalizeTasks(tasks, o.reqs);
    const ranked = rankHomeItems(rows, new Date(nowMs)).slice(0, 5);
    const byId = new Map(rows.map((r) => [r.id, r]));
    const alerts = buildAlerts(tasks, { approvalsPending: o.approvalsPending });
    const fr = freshness(o.loadedAt ?? null, o.sources, nowMs);
    host.replaceChildren(h('section', { class: 'kmi-pulse', 'data-testid': 'home-priority', 'aria-label': 'Önceliklerim' },
        h('div', { style: 'display:flex;justify-content:space-between;gap:8px;align-items:baseline;flex-wrap:wrap' }, h('h3', { style: 'margin:0 0 6px;font-size:14px' }, 'Önceliklerim'),
            h('span', { class: 'mu', 'data-testid': 'home-fresh', 'data-stale': String(fr.stale), style: `font-size:12px;${fr.stale ? 'color:#fbbf24' : ''}` }, fr.label, o.onRefresh ? h('button', { type: 'button', 'data-testid': 'home-refresh', onClick: o.onRefresh, style: 'margin-left:8px;min-height:28px' }, 'Yenile') : null)),
        alerts.length ? h('div', { 'data-testid': 'home-alerts', style: 'display:flex;gap:6px;flex-wrap:wrap;margin:0 0 8px' }, ...alerts.map((a) => h('a', { href: a.href, 'data-testid': 'home-alert', 'data-key': a.key, 'data-blocks': String(a.blocks), title: a.sample || a.label, style: `border:1px solid ${TONE[a.tone]};color:${TONE[a.tone]};border-radius:999px;padding:3px 10px;font-size:12px;font-weight:700;text-decoration:none;min-height:28px;display:inline-flex;align-items:center` }, `${a.blocks ? '⛔ ' : ''}${a.label}: ${a.count}`))) : null,
        ranked.length === 0 ? h('div', { class: 'mu', 'data-testid': 'home-priority-empty' }, 'Şu an açık göreviniz yok.')
            : h('ol', { style: 'margin:0;padding-left:20px;display:grid;gap:6px' }, ...ranked.map((r) => h('li', { 'data-testid': 'home-priority-item' },
                h('a', { href: byId.get(r.id)?.href ?? '#/gorevler', style: 'font-weight:700' }, r.title), h('div', { class: 'mu', style: 'font-size:12px' }, r.why)))),
        h('a', { href: '#/gorevler', class: 'mu', style: 'font-size:12px;display:inline-block;margin-top:6px' }, 'Tüm görevlerim →')));
}
